    @staticmethod
    def get_jason_response(raw_response: str):
        # Define the regular expression pattern to match JSON content within the triple backticks
        pattern = re.compile(r"```json(.+?)```", re.DOTALL)

        # Search for the pattern in the raw response
        match = pattern.search(raw_response)
        if not match:
            return None

        # Extract the JSON content and remove any leading or trailing whitespace
        json_content = match.group(1).strip()

        # Parse the JSON content
        return json.loads(json_content)


